import{_ as e,c as r,o as t,H as l}from"./chunks/framework.B03ETCDl.js";const d=JSON.parse('{"title":"생애최초로 주택청약 해보기","description":"","frontmatter":{"title":"생애최초로 주택청약 해보기","date":"2025-04-25T23:00+09:00","tags":["민영주택청약","생애최초 특별공급"]},"headers":[],"relativePath":"sleep/housing.md","filePath":"sleep/housing.md","lastUpdated":1779711796000}'),i={name:"sleep/housing.md"};function o(n,a,p,s,h,c){return t(),r("div",null,[...a[0]||(a[0]=[l('<h1 id="생애최초로-주택청약-해보기" tabindex="-1">생애최초로 주택청약 해보기 <a class="header-anchor" href="#생애최초로-주택청약-해보기" aria-label="Permalink to &quot;생애최초로 주택청약 해보기&quot;">​</a></h1><p>최근 거주 지역의 민영주택청약에 생애최초 특별공급으로 신청해서 서류 검수와 계약 체결을 진행하고 있어요. 주택청약 시 요구 조건과 신청 기준에 따른 증빙 서류는 청약자가 직접 꼼꼼히 확인하고 준비해야만 해요. 청약 신청 시 부적격 조건을 사전에 걸러내지 못하고 당첨된 이후에야 제출된 서류를 통해 부적격 여부를 판단하기 때문인데요. 매년 꽤 많은 사람들이 <a href="https://www.dailiang.co.kr/news/articleView.html?idxno=228407" target="_blank" rel="noreferrer">주택청약 당첨 뒤 부적격 처리</a>된다고 해요. 부적격 처리가 되더라도 청약통장이 사라지는 건 아니지만, 일정 기간 청약 신청 기회가 제한되므로 주의해야 해요.</p><p>민영주택청약의 <a href="https://kbthink.com/main/asset-management/wealth-manage-tip/kbthink-original/202411/first-place.html" target="_blank" rel="noreferrer">일반공급 1순위</a>는 해당 지역, 그리고 기타 지역 순서대로 기회가 주어지며 주택 전용면적에 따라 가점제와 추첨제로 진행돼요. 이때 가장 많이 부적격 사례가 발생하는 원인은 <a href="https://blog.toss.im/article/housing-5" target="_blank" rel="noreferrer">주택청약 신청 시 입력한 가점</a>이 당첨 후 서류로 확인한 실제 가점과 다른 경우라고 해요. 저는 일반공급이 아닌 **&#39;생애최초 특별공급&#39;**으로 청약을 신청했어요.</p><h2 id="생애최초-특별공급을-선택한-이유" tabindex="-1">생애최초 특별공급을 선택한 이유 <a class="header-anchor" href="#생애최초-특별공급을-선택한-이유" aria-label="Permalink to &quot;생애최초 특별공급을 선택한 이유&quot;">​</a></h2><p>일반공급 1순위 해당 지역이 아닌 생애최초 특별공급을 선택한 이유는 무주택 기간이 길지 않고 부양가족이 없어 가점제로는 당첨 가능성이 희박하다고 판단했기 때문이에요. 또한 현재 주택을 보유하고 계신 세대주 아버님이 만 60세 이상이셔서 주택청약 기준상 무주택 조건이 충족되었고, 덕분에 제가 &#39;무주택세대구성원&#39;으로서 신청할 수 있는 공고였기 때문이기도 해요.</p><p>사실 생애최초 특별공급으로 배정된 세대수가 그리 많지 않고 소득 기준을 확인하는 추첨제까지 거쳐야 해서, 이전 청약 사례(59㎡ 주택 특별공급 경쟁률 약 8대 1)를 고려했을 때 당첨 가능성이 낮을 거라 생각했어요. 그래서 일반공급 1순위도 함께 신청하려 했었죠. 그런데 특별공급 신청 결과를 확인해 보니 배정된 세대수보다 신청자 수가 적어서, 1인 가구 기준의 추첨 단계를 거치지 않고 사실상 바로 당첨된 상태가 되었어요. 이제 증빙 서류만 제대로 준비해서 제출하면 되는 상황이랍니다.</p><div class="tip custom-block github-alert"><p class="custom-block-title">TIP</p><p>특별공급에 신청하더라도 일반공급에 중복으로 신청하는 것은 가능해요. 단, 동일 세대 내에서 중복 청약은 불가능하므로 세대 구성원 간에 신청 여부를 사전에 꼭 공유해야 해요.</p></div><h2 id="생애최초-특별공급-신청-시-주의사항" tabindex="-1">생애최초 특별공급 신청 시 주의사항 <a class="header-anchor" href="#생애최초-특별공급-신청-시-주의사항" aria-label="Permalink to &quot;생애최초 특별공급 신청 시 주의사항&quot;">​</a></h2><p>생애최초 특별공급에 당첨된 후 서류 검증 과정에서 부적격 처리가 되면, 생애최초 특별공급 기회는 당첨 즉시 소멸하여 앞으로 다시는 신청할 수 없어요. 세대주가 만 60세를 넘었더라도 현재 거주 중인 세대의 주택을 부모님이 공동 명의로 보유하고 있다면, 주택을 소유한 세대 구성원인 부모님 모두가 만 60세를 넘으셔야 해요. 부모님의 과거 부동산 소유 이력이 불확실하다면 <a href="https://www.iros.go.kr/index.jsp" target="_blank" rel="noreferrer">인터넷등기소</a>에서 &#39;부동산소유현황&#39;을 미리 조회해 보시는 걸 추천해요.</p><ul><li>생애최초 특별공급은 등본상 세대구성원 전원이 과거에 주택을 소유한 이력이 단 한 번도 없어야 해요.</li><li>주택 공동 명의 여부와 주택 소유자의 만 60세 여부를 꼼꼼히 확인하지 않은 책임은 전적으로 신청자 본인에게 있어요.</li></ul><p>서류 심사 시 제출하는 모든 서류는 주민등록번호 뒷자리가 반드시 포함되어야 해요. 또한 재직증명서나 근로소득원천징수영수증 같은 일부 서류는 복사본이 아닌 원본이어야 하므로, 모집공고와 서류 제출 안내문을 토대로 견본주택(모델하우스) 측에 꼭 직접 문의해 보는 것이 가장 확실해요.</p><blockquote><p>모집공고문과 홈페이지에 별도로 공유된 서류 제출 안내문에 명시된 내용이 서로 다르거나 발급 기준이 애매한 부분이 있어 헷갈리기도 했어요.</p></blockquote><h2 id="생애최초-특별공급에서의-1인-가구-기준" tabindex="-1">생애최초 특별공급에서의 1인 가구 기준 <a class="header-anchor" href="#생애최초-특별공급에서의-1인-가구-기준" aria-label="Permalink to &quot;생애최초 특별공급에서의 1인 가구 기준&quot;">​</a></h2><p>민영주택청약 모집공고상 저는 일반공급 1순위 무주택세대구성원이면서 혼인을 하지 않은 &#39;1인 가구&#39;에 해당하여 추첨제로 청약이 가능해요. 1인 가구는 &#39;단독세대&#39;인 경우와 &#39;단독세대가 아닌 자&#39;로 나뉘는데요. 저는 현재 부모님과 함께 거주 중이며 주민등록표등본상 직계존속과 함께 등재되어 &#39;단독세대가 아닌 자&#39;에 해당해요. 덕분에 전용면적 60㎡를 초과하는 주택에도 신청할 수 있어서 모집공고 기준 가장 작은 주택면적인 70㎡로 신청했답니다.</p><ul><li>세대분리를 위해 임대차계약을 맺고 <strong>단독세대를 구성했다면 60㎡ 이하 주택에만 신청할 수 있어요.</strong> 이 기준을 확인하지 않고 초과 주택에 청약하면 부적격 대상이 되니 주의해야 해요.</li><li>만 30세를 넘어서 독립하지 않고 부모님 댁에 거주하는 <a href="https://www.joongang.co.kr/article/25328304" target="_blank" rel="noreferrer">캥거루족</a>이 &#39;단독세대가 아닌 자&#39;에 해당해요.</li></ul><h2 id="생애최초-특별공급-증빙-서류-준비하기" tabindex="-1">생애최초 특별공급 증빙 서류 준비하기 <a class="header-anchor" href="#생애최초-특별공급-증빙-서류-준비하기" aria-label="Permalink to &quot;생애최초 특별공급 증빙 서류 준비하기&quot;">​</a></h2><h3 id="_1-5개년도-소득세-납부-증빙" tabindex="-1">1. 5개년도 소득세 납부 증빙 <a class="header-anchor" href="#_1-5개년도-소득세-납부-증빙" aria-label="Permalink to &quot;1. 5개년도 소득세 납부 증빙&quot;">​</a></h3><p>생애최초 특별공급에 당첨되었다면 통산 5개년도에 대한 소득세 납부 사실을 증빙할 수 있는 서류가 필요해요. 한 직장에 5년 이상 계속 근무했다면 직인 날인이 포함된 &#39;근로소득원천징수영수증&#39;을 한 번에 신청해서 발급받으면 되지만, 이직 이력이 있다면 해당 연도들은 &#39;근로소득자용 소득금액증명원&#39;을 홈택스 등에서 발급받는 것이 훨씬 수월해요. 이때 5개년도는 연속될 필요가 없으며, 평생 동안 소득세를 납부한 내역이 총 5년만 증명되면 돼요.</p><ul><li>근로소득원천징수영수증은 팩스나 복사본이 아닌 반드시 주민등록번호 뒷자리가 포함된 <strong>원본</strong>으로 제출해야 해요.</li><li>저의 경우 재직 중인 회사에서 발급해 준 원천징수영수증 중 일부가 직인 날인이 인쇄된 복사본 형태여서 소득금액증명원으로 대체해서 제출했어요.</li></ul><h3 id="_2-자격-기준-증빙-서류" tabindex="-1">2. 자격 기준 증빙 서류 <a class="header-anchor" href="#_2-자격-기준-증빙-서류" aria-label="Permalink to &quot;2. 자격 기준 증빙 서류&quot;">​</a></h3><p>무주택세대구성원으로서 생애최초 특별공급에 당첨되었다면, 주민등록표등본에 기재된 형제자매를 제외한 모든 세대구성원 기준의 증빙 서류가 필요해요. 따라서 저를 포함해 직계존속인 아버지와 어머니에 대한 서류를 발급받아 제출해야 했어요. 간이과세자이신 아버지는 사업자등록증 사본을 준비하셔야 했고, 근로자이신 어머니는 재직 중이신 회사에 (아파트 계약 증빙용) 재직증명서 발급을 요청해야 했답니다.</p><ul><li>직인 날인된 재직증명서 (또는 사업자등록증 사본)</li><li>과거 변동사항이 모두 기재된 <a href="https://www.gov.kr/portal/service/serviceInfo/PTR000050333" target="_blank" rel="noreferrer">건강보험자격득실확인서</a></li></ul><p>※ 세대 구성원의 재직증명서 역시 주민등록번호 뒷자리가 모두 표시되어야 하므로, 회사에 요청할 때 &#39;아파트 계약용&#39; 또는 &#39;주택공급 계약용&#39;으로 발급을 신청해 주세요.</p><h3 id="_3-소득-및-자산-기준-증빙-서류" tabindex="-1">3. 소득 및 자산 기준 증빙 서류 <a class="header-anchor" href="#_3-소득-및-자산-기준-증빙-서류" aria-label="Permalink to &quot;3. 소득 및 자산 기준 증빙 서류&quot;">​</a></h3><p>1인 가구 추첨 단계 없이 바로 당첨된 상태이지만, 소득 기준을 충족했음은 서류로 완벽히 증빙해야 해요. 3인 가구 기준으로 **세대 월평균 소득이 160% 이하(11,528,499원 이하)**임을 서류로 보여주어야 하는데요. 생애최초 특별공급 당첨자의 모든 세대 구성원은 자격 및 소득 검증을 위한 서류를 발급받아야 해요. 만약 입주자모집공고일이 7월 이전이라면 간이과세자의 전년도 소득금액증명 발급이 불가능하므로, <strong>전전년도 소득금액증명</strong>을 발급받아 제출해야 해요.</p><ul><li><p>직인 날인된 재직증명서 또는 사업자등록증 사본</p></li><li><p>직인 날인된 전년도 근로소득원천징수영수증 또는 전년도(혹은 전전년도) 소득금액증명원</p></li><li><p>피부양 직계존속(아버지, 어머니)의 주민등록표 초본 (상세 내역 포함)</p></li><li><p>소득 기준을 초과한 경우에도 모든 세대원의 부동산 자산가액 합계가 3억 3,100만 원 이하임을 증명할 수 있으면 적격 처리가 돼요.</p></li><li><p>자산 기준을 증빙하기 위해 요구되는 서류들은 발급 절차가 다소 복잡한 편이에요.</p></li></ul><blockquote><p>근로자라면 근로소득원천징수영수증상 총급여액을, 간이과세자라면 소득금액증명원의 소득금액을 12로 나누어 월평균 소득을 산출한 뒤 모든 세대원의 소득을 합산하면 돼요. 서류 검증 시 검수자의 도움을 받아 직접 확인해 보니 저희 세대는 약 700만 원 선으로 안전하게 적격 기준을 충족했어요.</p></blockquote><p>처음에는 당첨이 너무 쉽게 되어버려 오히려 준비하고 증빙해야 할 서류가 많아 복잡하고 걱정도 많았어요. 미리 계산해 본 소득 기준이 잘못되었을까 봐 조마조마했지만, 다행히 보완 요청 없이 무사히 아파트 공급 계약을 체결할 수 있었답니다.</p><hr><h2 id="정당-계약-당첨자-공급계약-체결-시-필요한-서류" tabindex="-1">정당 계약(당첨자 공급계약 체결) 시 필요한 서류 <a class="header-anchor" href="#정당-계약-당첨자-공급계약-체결-시-필요한-서류" aria-label="Permalink to &quot;정당 계약(당첨자 공급계약 체결) 시 필요한 서류&quot;">​</a></h2><p>서류 심사를 무사히 통과하고 적격 판정을 받아 접수 확인증을 받았다면, 정당 계약 당일에 아래의 서류들을 지참하여 방문해야 해요.</p><ul><li><p>신분증 사본 (견본주택에서 현장 복사 가능)</p></li><li><p>공통 및 생애최초 특별공급 자격검증서류 접수 확인증</p></li><li><p>본인서명사실확인서 또는 인감증명서 (아파트 계약용)</p></li><li><p>분양대금 및 발코니 확장 공사비 무통장 입금 영수증</p></li><li><p>인지세 납부를 위한 종이문서용 전자수입인지</p></li><li><p>서류 제출 시 인감증명서를 함께 제출했다면, 계약 당일에는 인감도장만 지참하시면 돼요.</p></li><li><p>분양대금 납부 계좌와 발코니 확장비 납부 계좌가 서로 다르므로 송금 시 반드시 확인해야 해요.</p></li><li><p>인지세의 경우, 계약 체결 후 공급계약서를 수령하고 나서 우체국이나 인터넷을 통해 전자수입인지를 구매해 첨부하면 돼요.</p></li></ul><p>계약 안내문에는 무통장 입금 영수증 지참이 필수라고 안내되어 있었지만, 현장에서는 따로 영수증 실물을 까다롭게 대조하지는 않고 견본주택 시스템에 수납된 정보를 토대로 확인하여 계약서에 첨부해 주더라고요. 또한 에어컨 등의 유상 옵션 선택은 정당 계약일에 함께 진행하지 않고, 추후 별도 일정을 통해 계약한다고 안내받았어요. 이 주택의 경우 계약금은 분양대금의 5%였고, <strong>1차 계약금 500만 원</strong>을 먼저 납부한 뒤 나머지 잔여 계약금은 계약일로부터 30일 이내에 지정된 계좌로 입금하도록 되어 있었어요.</p><div class="warning custom-block github-alert"><p class="custom-block-title">WARNING</p><p>계약금 입금이 일부 지연되더라도 즉시 계약이 해지되지는 않지만, 연 15% 수준의 높은 연체 이자가 발생해요. 또한 계약 체결 이후 마음이 바뀌어 계약을 해제할 경우 분양대금의 10%에 해당하는 위약금이 발생한다는 사실도 안내받았어요.</p></div><hr><h2 id="중도금-대출-신청-및-유의사항" tabindex="-1">중도금 대출 신청 및 유의사항 <a class="header-anchor" href="#중도금-대출-신청-및-유의사항" aria-label="Permalink to &quot;중도금 대출 신청 및 유의사항&quot;">​</a></h2><p>계약 체결 과정에서 상담 직원을 통해 중도금 대출 협약 은행은 아직 확정되지 않았으며, 중도금 1차 납부일 기준 약 한 달 전에 개별 문자로 안내될 것이라는 답을 들었어요. 본 청약 단지는 중도금 대출 무이자 혜택이 제공되는데, 추후 지정되는 은행을 통해 집단 중도금 대출을 신청해야 해요.</p><p>비규제지역이고 생애최초 특별공급 대상자이므로 LTV 80%가 적용되어 중도금 60% 전체 대출이 가능해요. 대출 이자는 무이자로 진행되지만, 계약자가 직접 납부해야 하는 비용도 존재하는데요. 바로 <a href="https://www.khug.or.kr/hug/web/ig/hp/ighp000001.jsp" target="_blank" rel="noreferrer">주택구입자금보증</a> 수수료인 대출금의 연 0.13%에 해당하는 보증료와 인지세예요. 추가로 중도금 1차 납부일에 발코니 확장 공사비 및 유상 옵션에 대한 중도금은 대출이 되지 않으므로 직접 계좌로 납부해야 해요.</p><ul><li>정당 계약 시의 납부 계좌와 다르게, 중도금 대출이 실행되면 은행에서 대출 전용 계좌를 통해 직접 상환 및 납부가 이루어져요.</li><li>사업주체가 이자를 대납해 주는 무이자 대출 조건인 경우, 연말정산 시 <a href="https://www.nts.go.kr/nts/cm/cntnts/cntntsView.do?mi=40608&amp;cntntsId=239020" target="_blank" rel="noreferrer">장기주택저당차입금 이자상환액 소득공제</a> 혜택은 적용받을 수 없어요.</li></ul><hr><h2 id="잔금대출-계획-세우기" tabindex="-1">잔금대출 계획 세우기 <a class="header-anchor" href="#잔금대출-계획-세우기" aria-label="Permalink to &quot;잔금대출 계획 세우기&quot;">​</a></h2><p>입주 시기가 되면 한국주택금융공사의 <a href="https://www.hf.go.kr/ko/sub01/sub01_02_01.do#" target="_blank" rel="noreferrer">디딤돌대출</a>을 DSR 40% 기준으로 신청하고, 그래도 자금이 부족하다면 <a href="https://www.hf.go.kr/ko/sub01/sub01_01_01.do" target="_blank" rel="noreferrer">보금자리론</a>으로 DTI 60% 한도 내에서 추가 대출을 받는 방법을 고려할 수 있어요.</p><p>하지만 <strong>2025년 7월부터 디딤돌대출의 후취담보 취급이 금지</strong>되기 때문에, 입주예정자협의회 등을 통해 협약된 은행의 후취담보 집단대출을 먼저 이용해야 할 것 같아요. 보금자리론의 금리가 다소 높은 편이라 입주 시기가 다가왔을 때 두 상품을 면밀히 비교해 봐야 할 것 같아요.</p><blockquote><p>생애최초 특례구입자금보증을 통해 담보주택 가격의 LTV 80%까지 대출 한도가 나오더라도, 디딤돌대출 and 보금자리론 자체의 조건 한계로 대출이 제한될 수 있어요. 또한 무주택 세대주 자격을 갖추기 위해 세대분리를 하더라도, 만 30세 미만이거나 30세 이상이더라도 단독세대주 요건에 맞지 않으면 대출 이용이 불가능할 수 있으니 꼼꼼한 확인이 필요해요.</p></blockquote><hr><h2 id="취득세와-채권-비용-산정" tabindex="-1">취득세와 채권 비용 산정 <a class="header-anchor" href="#취득세와-채권-비용-산정" aria-label="Permalink to &quot;취득세와 채권 비용 산정&quot;">​</a></h2><p>중도금 6회차 납부가 모두 끝나고 입주예정일이 다가오면, 잔금 납부와 함께 중도금 대출 원리금 상환을 위한 잔금대출을 실행하게 돼요. 이때 대출 실행에 따른 설정채권 비용과 소유권 이전 등기를 위한 <strong>국민주택채권</strong> 매입 비용이 발생해요. 또한 분양가, 발코니 확장비, 유상 옵션을 모두 포함한 실제 취득가액 기준으로 취득세(1%)와 지방교육세(0.1%)를 납부해야 한답니다. 등기 수수료(증지대 및 인지세 등)도 예산에 포함해 두어야 해요.</p><ul><li>공동주택 취득 시 농어촌특별세가 부과되기도 하지만, 전용면적 85㎡ 이하의 주택은 비과세 대상에 해당해요.</li><li>상세한 등기 관련 부대비용은 <a href="https://xn--989a00af8jnslv3dba.com/%EB%93%B1%EA%B8%B0%EB%B9%84%EC%9A%A9" target="_blank" rel="noreferrer">부동산 계산기</a>를 통해 대략적으로 시뮬레이션해 볼 수 있어요.</li></ul><h3 id="생애최초-취득세-감면-혜택" tabindex="-1">생애최초 취득세 감면 혜택 <a class="header-anchor" href="#생애최초-취득세-감면-혜택" aria-label="Permalink to &quot;생애최초 취득세 감면 혜택&quot;">​</a></h3><p>이번 청약 단지는 실거주 의무가 없는 조건이지만, 생애최초 주택 구입자에게 주어지는 <a href="https://www.banksalad.com/articles/25%EB%85%84-%EC%83%9D%EC%95%A0%EC%B5%9C%EC%B4%88-%EC%A3%BC%ED%83%9D-%EC%B7%A8%EB%93%9D%EC%84%B8-%EA%B0%90%EB%A9%B4-%ED%98%9C%ED%83%9D-%EC%B4%9D%EC%A0%95%EB%A6%AC" target="_blank" rel="noreferrer">취득세 감면 혜택</a>을 적용받으려면 <strong>3년 동안의 지자체 실거주 의무</strong>를 준수해야 해요.</p><p>저는 투자가 아닌 실제 거주를 목적으로 분양받은 아파트이기 때문에 무조건 감면 혜택을 받는 것이 유리하다고 판단했어요. 실거주 요건을 채우지 못해 감면받은 취득세가 추징되고 가산세를 무는 리스크를 피하려면, 처음부터 실거주 요건을 철저히 지키며 감면 혜택을 누리는 것이 합리적인 선택이랍니다.</p>',51)])])}const b=e(i,[["render",o]]);export{d as __pageData,b as default};
